-- Canonical transactional contract for the initial content-free AI controls.
begin;
create extension if not exists pgtap with schema extensions;
select plan(15);
select has_table('private','ai_processing_config','AI kill switch and caps exist');
select has_table('private','ai_parse_jobs','content-free AI usage ledger exists');
select has_function('public','reserve_ai_parse',array['uuid','uuid','text','text','integer','integer'],'durable reservation RPC exists');
select ok(not has_table_privilege('authenticated','private.ai_parse_jobs','select'),'clients cannot read private AI audit rows');
select ok(not has_function_privilege('anon','public.reserve_ai_parse(uuid,uuid,text,text,integer,integer)','execute'),'anonymous reservations denied');
select ok(not has_function_privilege('authenticated','public.mark_ai_parse_started(uuid,text)','execute'),'clients cannot forge provider job state');
select ok(has_function_privilege('service_role','public.mark_ai_parse_started(uuid,text)','execute'),'only server role can record provider job state');
insert into auth.users(id) values ('50000000-0000-0000-0000-000000000001'),('50000000-0000-0000-0000-000000000002');
insert into public.households(id,name,created_by) values ('60000000-0000-0000-0000-000000000001','AI test household','50000000-0000-0000-0000-000000000001');
insert into public.household_members(household_id,user_id,display_name,role) values ('60000000-0000-0000-0000-000000000001','50000000-0000-0000-0000-000000000001','Member','owner');
set local role authenticated;
set local request.jwt.claim.sub='50000000-0000-0000-0000-000000000001';
select throws_ok($$select public.reserve_ai_parse('60000000-0000-0000-0000-000000000001','70000000-0000-0000-0000-000000000001','v1','application/pdf',1000,1)$$,'P0001','AI processing is disabled','database kill switch defaults off');
reset role;
update private.ai_processing_config set provider_enabled=true,monthly_household_page_cap=10;
set local role authenticated;
set local request.jwt.claim.sub='50000000-0000-0000-0000-000000000001';
select lives_ok($$select public.reserve_ai_parse('60000000-0000-0000-0000-000000000001','70000000-0000-0000-0000-000000000001','v1','application/pdf',1000,1)$$,'first parse is reserved');
select is((select job_id from public.reserve_ai_parse('60000000-0000-0000-0000-000000000001','70000000-0000-0000-0000-000000000001','v1','application/pdf',1000,1)),(select job_id from public.reserve_ai_parse('60000000-0000-0000-0000-000000000001','70000000-0000-0000-0000-000000000001','v1','application/pdf',1000,1)),'same idempotency key returns the same reservation');
select lives_ok($$select public.reserve_ai_parse('60000000-0000-0000-0000-000000000001','70000000-0000-0000-0000-000000000002','v1','application/pdf',1000,1)$$,'second parse is reserved');
select lives_ok($$select public.reserve_ai_parse('60000000-0000-0000-0000-000000000001','70000000-0000-0000-0000-000000000003','v1','application/pdf',1000,1)$$,'third parse is reserved');
select throws_ok($$select public.reserve_ai_parse('60000000-0000-0000-0000-000000000001','70000000-0000-0000-0000-000000000004','v1','application/pdf',1000,1)$$,'P0001','AI parse hourly limit reached','fourth parse inside one hour is rejected');
select throws_ok($$select public.reserve_ai_parse('60000000-0000-0000-0000-000000000001','70000000-0000-0000-0000-000000000005','v1','application/pdf',5000000,1)$$,'P0001','Sanitized derivative is too large','oversized derivative is rejected');
reset role;
set local role authenticated;
set local request.jwt.claim.sub='50000000-0000-0000-0000-000000000002';
select throws_ok($$select public.reserve_ai_parse('60000000-0000-0000-0000-000000000001','70000000-0000-0000-0000-000000000006','v1','application/pdf',1000,1)$$,'P0001','Active household membership is required','unrelated user cannot reserve household parsing');
reset role;
select * from finish();
rollback;
